//! A directive value's `name={` prefix belongs to its first line only. Once the
//! open tag has wrapped, prettier measures each group of the value against the
//! column it starts at, so a continuation line has the whole width minus its
//! own indent. This port charged the prefix to the whole value by narrowing the
//! print width, which re-broke continuation lines that fit (#4119) — and the
//! per-shape discounts that had been bolted on to soften that (an arrow's body,
//! an object literal) under-charged the first line instead, leaving an object
//! flat past the print width where the oracle expands it.
//!
//! Every expectation here was generated by running the input through the
//! oxfmt(`svelte: true`) oracle. `name15_control` sits one column inside the
//! old threshold and must not move; `chain_fits_flat` never wraps at all.

use rsvelte_formatter::{
    FormatOptions, IndentStyle, IndentWidth, JsFormatOptions, LineWidth, format,
};

fn fmt(src: &str) -> String {
    let js = JsFormatOptions {
        indent_style: IndentStyle::Space,
        indent_width: IndentWidth::try_from(2u8).unwrap(),
        line_width: LineWidth::try_from(80u16).unwrap(),
        ..JsFormatOptions::default()
    };
    let options = FormatOptions {
        js,
        typescript: false,
        ..FormatOptions::new()
    };
    format(src, &options).expect("format ok")
}

