#[test]
fn every_cell_formats_to_the_oracle_output() {
    let mut wrong = Vec::new();
    for (name, input, expected) in CELLS {
        let got = fmt(input);
        if got != *expected {
            wrong.push(format!("{name}: got {got:?}, want {expected:?}"));
        }
    }
    assert!(wrong.is_empty(), "{}", wrong.join("\n"));
}

/// Liveness: the table has to carry a value that breaks exactly once at its top
/// operator, one whose literal expands, and one that stays flat, or it measures
/// one direction of the budget.
#[test]
fn the_table_carries_every_direction() {
    let once = CELLS
        .iter()
        .filter(|(_, _, want)| want.contains("&&\n") && !want.contains("===\n"))
        .count();
    let expands = CELLS
        .iter()
        .filter(|(_, _, want)| want.contains("={{\n"))
        .count();
    let flat = CELLS
        .iter()
        .filter(|(_, _, want)| {
            want.lines()
                .any(|l| l.find("={").is_some_and(|i| l[i..].contains('}')))
        })
        .count();
    assert!(once > 0, "no cell breaks once at its top-level operator");
    assert!(expands > 0, "no cell expands an object literal");
    assert!(flat > 0, "no cell keeps its value flat");
}

/// Formatting the oracle's own output has to be a fixed point: the wrapped
/// form is the one a user's file holds after the first run.
#[test]
fn the_oracle_output_is_a_fixed_point() {
    let mut wrong = Vec::new();
    for (name, _, expected) in CELLS {
        let got = fmt(expected);
        if got != *expected {
            wrong.push(format!("{name}: {got:?}"));
        }
    }
    assert!(wrong.is_empty(), "{}", wrong.join("\n"));
}
